head.script:
// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거). 2026-11
scwin.__getDom = function(id) {
	var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
	var r = d(id); if (r) return r;
	var s = dd(P + id); r = d(s); if (r) return r;
	var g = s.indexOf('G_');
	if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
	return d(s.replace(P, ''));
};

scwin.onpageload = function() {
	windowContainer1.createWindow({
		title : 'icon_left일때',
		src : '/sample/common_link/windowContainer_MDI_TAB_icon_WESD-1044_(WSQ-5066)_sub0.xml',
		openAction : 'existWindow',
		userIconClass : "w2windowContainer_nameLayer_imageIcon1",
		userIconPosition : "left"
	});
	windowContainer1.createWindow({
		title : 'icon없을때',
		src : '/sample/common_link/windowContainer_MDI_TAB_icon_WESD-1044_(WSQ-5066)_sub1.xml',
		openAction : 'existWindow'
	});
	windowContainer1.createWindow({
		title : 'icon_right일때',
		src : '/sample/common_link/windowContainer_MDI_TAB_icon_WESD-1044_(WSQ-5066)_sub2.xml',
		openAction : 'existWindow',
		userIconClass : "w2windowContainer_nameLayer_imageIcon2",
		userIconPosition : "right"
	});
	windowContainer1.createWindow({
		title : 'iconPosition없을때',
		src : '/sample/common_link/windowContainer_MDI_TAB_icon_WESD-1044_(WSQ-5066)_sub3.xml',
		openAction : 'existWindow',
		userIconClass : "w2windowContainer_nameLayer_imageIcon4"
	});
};

scwin.checkVal = function() {
	return scwin.__getDom('windowContainer1_nameLayer_' + $p.id + 'windowContainer1_subWindow0').children.length == 3;
};
